APEX_USE_CPP=1 ./.venv/Scripts/python.exe -c "
import numpy as np, trimesh
from pipeline.step1_ingest import _find_self_intersecting_faces as fsi, _triangles_cross as cross
def depth(A,B):
    n=np.cross(B[1]-B[0],B[2]-B[0]); n/=np.linalg.norm(n)
    d=(A-B[0])@n
    return min(-d.min(), d.max()) if d.min()<0<d.max() else 0.0
R='research/S4_Slicer/output_models/folds_real_overhang_m'
for f in ['1_pass2_ovh30','1_pass3_ovh30','2_pass1_ovh30','2_pass3_ovh30','1_pass7_ovh0','1_pass12_ovh0']:
    try: m=trimesh.load(R+f+'.stl')
    except Exception as e: print(f,'absent'); continue
    bad=np.array(sorted(fsi(m))); T=m.triangles; F=m.faces; dep=[]
    for ii,i in enumerate(bad):
        for j in bad[ii+1:]:
            if set(F[i])&set(F[j]): continue
            if cross(T[i],T[j]): dep.append(min(depth(T[i],T[j]),depth(T[j],T[i])))
    ext=np.ptp(m.triangles_center[bad],axis=0).max() if len(bad) else 0
    dep=np.array(dep) if dep else np.zeros(1)
    print(f'real_overhang m{f:<14}: {len(bad)} faces, aire {m.area_faces[bad].sum() if len(bad) else 0:.1f} mm2 / {m.area:.0f} ({100*(m.area_faces[bad].sum() if len(bad) else 0)/m.area:.1f} %), etendue {ext:.1f} mm, enfoncement median {np.median(dep):.3f} max {dep.max():.3f} mm')
" 2>&1 | grep -v -i warn

