function setBusy(busy, stepLabel, pct) {
  document.getElementById("btn-iterate").disabled = busy;
  document.getElementById("btn-reset").disabled = busy;
  document.getElementById("progress-wrap").style.display = busy ? "block" : "none";

  const bar = document.getElementById("progress-bar");
  const label = document.getElementById("progress-label");

  if (!busy) {
    label.textContent = "";
    return;
  }

  if (pct === null || pct === undefined) {
    // pas de % applicable pour cette etape (ingestion, export STL...)
    bar.classList.add("indeterminate");
    bar.style.width = "";
    label.textContent = stepLabel || "calcul en cours...";
  } else {
    bar.classList.remove("indeterminate");
    bar.style.width = pct + "%";
    label.innerHTML = `${stepLabel || "calcul en cours"} -- <span id="progress-pct">${pct}%</span>`;
  }
}

function renderInfo(state) {
  document.getElementById("model-name").textContent = state.model_name || "-";
  document.getElementById("counter").textContent = state.iteration;

  if (state.error) {
    document.getElementById("error").textContent = "Erreur: " + state.error;
  } else {
    document.getElementById("error").textContent = "";
  }

  const info = state.last_info;
  const infoEl = document.getElementById("info");
  if (info) {
    infoEl.innerHTML =
      `tetraedres: ${state.number_of_cells}<br>` +
      `cout rotation (least_squares): ${info.rotate_cost.toExponential(3)}<br>` +
      `cout deformation (least_squares): ${info.deform_cost.toExponential(3)}<br>` +
      `fraction en surplomb: ${(info.overhang_fraction * 100).toFixed(2)}%<br>` +
      `temps: ${info.elapsed_s}s`;
  } else {
    infoEl.textContent = state.number_of_cells ? `tetraedres: ${state.number_of_cells} (aucune iteration encore)` : "en attente...";
  }

  const histEl = document.getElementById("history");
  histEl.innerHTML = state.history.map((h, i) =>
    `<div>#${i + 1}: rot=${h.rotate_cost.toExponential(2)} deform=${h.deform_cost.toExponential(2)} surplomb=${(h.overhang_fraction * 100).toFixed(1)}%</div>`
  ).reverse().join("");
}

async function pollProgress() {
  try {
    const res = await fetch("/progress");
    const data = await res.json();
    if (data.busy) {
      setBusy(true, data.progress_step, data.progress_pct);
    } else {
      setBusy(false);
      clearInterval(pollTimer);
      pollTimer = null;
      await refreshStateAndModel();
    }
  } catch (e) {
    // silencieux : le poll retentera au prochain tick
  }
}

async function refreshStateAndModel() {
  const res = await fetch("/state");
  const state = await res.json();
  fillParams(state.default_params);
  renderInfo(state);
  loadModel();
}

async function onIterate() {
  const params = readParams();
  setBusy(true, "envoi de la requete...");
  const res = await fetch("/iterate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(params),
  });
  if (!res.ok) {
    const data = await res.json();
    setBusy(false);
    document.getElementById("error").textContent = "Erreur: " + (data.error || res.statusText);
    return;
  }
  if (!pollTimer) pollTimer = setInterval(pollProgress, 300);
}

async function onReset() {
  setBusy(true, "reinitialisation (nouvelle tetraedrisation)...");
  const res = await fetch("/reset", { method: "POST" });
  if (!res.ok) {
    const data = await res.json();
    setBusy(false);
    document.getElementById("error").textContent = "Erreur: " + (data.error || res.statusText);
    return;
  }
  if (!pollTimer) pollTimer = setInterval(pollProgress, 300);
}

document.getElementById("btn-iterate").addEventListener("click", onIterate);
document.getElementById("btn-reset").addEventListener("click", onReset);

initViewer();
refreshStateAndModel();
</script>
</body>
</html>

