import numpy as np, potpourri3d as pp3d, time
from test_surface_paths import disk, hemisphere
from surface_paths import boundary_loops
for maker in (disk, hemisphere):
    name, zm, exact_b, exact_c, f = maker()
    loops = boundary_loops(zm.F)
    curves = [[(int(i), []) for i in np.r_[lp, lp[:1]]] for lp in loops]
    res = {}
    for tc in (1.0, 0.3, 0.1):
        t=time.time(); d = np.asarray(pp3d.MeshHeatMethodDistanceSolver(zm.V, zm.F, t_coef=tc).compute_distance_multisource(list(map(int, zm.boundary)))); res[f'chaleur t={tc}'] = (d, time.time()-t)
    t=time.time()
    try:
        sh = pp3d.MeshSignedHeatSolver(zm.V, zm.F); d = np.abs(np.asarray(sh.compute_distance(curves, [True]*len(curves), [])).ravel()); res['chaleur signee'] = (d, time.time()-t)
    except Exception as e: print('signee :', e)
    t=time.time(); d = zm.distance_to_boundary(); res['fast marching'] = (d, time.time()-t)
    for k,(d,tt) in res.items():
        e = np.abs(d-exact_b)
        print(f'{name:<12} bord, {k:<16}: ecart median {np.median(e):.3f} 95e {np.percentile(e,95):.3f} max {e.max():.3f} ({tt:.2f} s)')
