    if pattern == "hilbert":
        uv, frac = sp.hilbert_stretch(zm)
        if remedy == "B":
            fn, kw = sp.hilbert_split, {"edge_rings": edge_rings, "edge_overlap": edge_overlap}
            edge_rings = 0                                  # cordons poses morceau par morceau
        elif remedy == "C":
