def _finish(zm, face_normals, res, thickness):
    vn = vertex_normals(zm, face_normals)
    tree = cKDTree(zm.V)
    paths, normals = [], []
    for p in res.paths:
        if len(p) < 2:
            continue
        p = resample(p)
        n = vn[tree.query(p)[1]]
