def merge_micro_zones(skin, width, micro_inradius):
    """Rattache chaque micro-zone (plus grande distance au bord < micro_inradius :
    trop etroite pour un cordon de bord et un motif) a une zone VOISINE
    (arete commune), choisie parmi celles ou la fusion reste imprimable : la
    zone fusionnee s'imprime au plus tard des deux moments, qui doit rester
    <= au dernier moment accessible de TOUTES ses faces (P2-bis). Parmi les
    voisines admissibles : la plus longue frontiere commune. Une micro-zone
    sans voisine admissible reste seule et est signalee. Decision utilisateur
    du 2026-09-28."""
    zone = skin["zone"].copy()
    moment = {z: int(m) for z, m in enumerate(skin["zone_moment"])}
    last = skin["last_access"]
    V, F = skin["vertices"], skin["faces"]
    e = np.concatenate([F[:, [0, 1]], F[:, [1, 2]], F[:, [2, 0]]])
    fid = np.tile(np.arange(len(F)), 3)
    key = np.sort(e, axis=1)
    order_ = np.lexsort((key[:, 1], key[:, 0]))
    key, fid, e = key[order_], fid[order_], e[order_]
    same = np.all(key[1:] == key[:-1], axis=1)
    pa, pb = fid[:-1][same], fid[1:][same]                      # paires de faces voisines
    elen = np.linalg.norm(V[key[:-1][same, 0]] - V[key[:-1][same, 1]], axis=1)

    def inradius(z):
        faces = np.flatnonzero(zone == z)
        try:
            return float(sp.ZoneMesh(V, F[faces]).distance_to_boundary().max())
        except Exception:
            return 0.0

    log, unmerged = [], []
    todo = [z for z in moment if (zone == z).any()]
    changed = True
    while changed:
        changed = False
        for z in sorted(todo, key=lambda q: skin["areas"][zone == q].sum()):
            if not (zone == z).any() or inradius(z) >= micro_inradius:
                continue
            za, zb = zone[pa], zone[pb]
            border = {}
            for q, w in zip(np.where(za == z, zb, za)[(za == z) ^ (zb == z)], elen[(za == z) ^ (zb == z)]):
                if q >= 0:
                    border[int(q)] = border.get(int(q), 0.0) + float(w)
            best = None
            for q, length in border.items():
                m = max(moment[z], moment[q])
                if m <= last[(zone == z) | (zone == q)].min() and (best is None or length > best[1]):
                    best = (q, length, m)
            if best is None:
                if z not in unmerged:
                    unmerged.append(z)
                continue
            q, length, m = best
            zone[zone == z] = q
            log.append((z, q, moment[z], moment[q], m, length))
            moment[q] = m
            changed = True
    return zone, moment, log, unmerged


