.leftSidebarContainer {
  position: fixed;
  left: 24px;
  top: 212px;
  display: flex;
  flex-direction: column;
  z-index: 1000;
  pointer-events: none;
}

.categoriesToolbar {
  display: flex;
  flex-direction: row;
  width: 293px;
  max-width: 293px;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-behavior: smooth;
  gap: 6px;
  pointer-events: auto;
  background: rgba(10, 15, 26, 0.25);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  padding: 8px;
  border-radius: 20px;

  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }

  > div {
    width: auto;
    flex: 0 0 auto;
    transition: opacity 0.2s ease;
  }

  // Pendant un morphing (cf. LiquidGlassMorph), le verre animé tient lieu de fond : la pilule
  // perd le sien instantanément (aucune transition, sinon il se superposerait au verre animé) et
  // son contenu s'estompe.
  &.morphing {
    background: transparent;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;

    > div {
      opacity: 0;
    }
  }
}

.categoryButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: auto;
  lastIndex: number;
  isPlaying: boolean;
  togglePlay: () => void;
  seek: (value: number) => void;
  speed: number;
  setSpeed: (speed: number) => void;
  openFilePicker: () => void;
}

// `active` (isPreviewActive) devient vrai dans `onCovered` (cf. Sidebar.tsx), à l'instant précis
// où le rideau plein écran (SpaceTransitionOverlay) vient de finir de se peindre — PAS quand il a
// fini de se lever. À ce même instant démarrent aussi, tous masqués par le rideau : la mitose
// pilule → panneaux de CategoriesSidebar (PREVIEW_MORPH_MS = 1370ms) et le déplacement de la barre
// d'aide TopRightMenu (RESHAPE_DURATION = 1100ms) — les deux plus longues animations de la
// séquence. Le rideau lui-même reste peint (phase "text") 1000ms puis met 575ms à se lever
