{/* Même chose autour de Prévisualisation : disparition dès le clic (enteringPreview),
    et, à la sortie, pilule remontée icônes cachées pendant toute la fusion inverse
    ('reverse'), puis cascade d'apparition une fois sa forme reprise. Piloté ici et
    non par `.morphing > div` : cet enfant est en `display: contents`, sur lequel
    l'opacité CSS n'a aucun effet. */}
<motion.div
  variants={pillIconsContainerVariants}
  initial={wasArrivingFromModeling || previewMorphPhase === 'reverse' ? 'hidden' : false}
  animate={leavingToModeling || enteringPreview || previewMorphPhase !== null ? 'hidden' : 'visible'}

