                                  double* closest) const {
    for (std::size_t i = begin; i < end; ++i) {
        const Vec3 p{points[3 * i], points[3 * i + 1], points[3 * i + 2]};
        Vec3 q;
        out[i] = query(p, &q);
        if (closest) {
            closest[3 * i] = q.x;
            closest[3 * i + 1] = q.y;
            closest[3 * i + 2] = q.z;
        }
